#include <nuttx/config.h>

#include <unistd.h>
#include <uv.h>
#include <lvgl/lvgl.h>

#include "aura_ui.h"

static void aura_lvgl_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
  lv_nuttx_uv_t uv_info;
  void *data;
  uv_loop_init(loop);
  lv_memset(&uv_info, 0, sizeof(uv_info));
  uv_info.loop = loop;
  uv_info.disp = result->disp;
  uv_info.indev = result->indev;
#ifdef CONFIG_UINPUT_TOUCH
  uv_info.uindev = result->utouch_indev;
#endif
  data = lv_nuttx_uv_init(&uv_info);
  uv_run(loop, UV_RUN_DEFAULT);
  lv_nuttx_uv_deinit(&data);
  uv_loop_close(loop);
}

int aura_space_main(int argc, char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  uv_loop_t loop;
  (void)argc;
  (void)argv;

  if (lv_is_initialized()) {
    LV_LOG_ERROR("LVGL already initialized");
    return 1;
  }

  lv_init();
  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, &result);
  if (result.disp == NULL) {
    LV_LOG_ERROR("Aura Space: display initialization failed");
    lv_deinit();
    return 1;
  }

  lv_memset(&loop, 0, sizeof(loop));
  aura_ui_start();
  aura_lvgl_loop(&loop, &result);
  aura_ui_stop();
  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
